using System.Net;
using System.Text.Json;
using Htt.Host.Api.Accounting;
using Htt.Infrastructure;
using Npgsql;
using Xunit;
using static Htt.IntegrationTests.SalesFlowSupport;
namespace Htt.IntegrationTests;
public sealed class GeneralBankingTests:IAsyncLifetime
{
 private readonly DatabaseFixture db=new();public Task InitializeAsync()=>db.InitializeAsync();public Task DisposeAsync()=>db.DisposeAsync();private static int serial;
 private Task<object?> S(string sql,params(string,object)[]args)=>db.OwnerScalarAsync(sql,args);
 private static Guid Id(JsonElement x)=>x.GetProperty("id").GetGuid();private static Guid Tid(JsonElement x)=>Id(x.GetProperty("transaction"));
 private async Task<DateOnly> Today()=>DateOnly.Parse((string)(await S("SELECT((now()AT TIME ZONE timezone)::date)::text FROM core.companies WHERE id=@company",("company",db.Company)))!);
 private async Task<Guid> Bank(HttpClient c,string kind="BANK")=>await Create(c,"/bank-accounts",new BankAccountInput(Code(),"C01 bank",kind,kind=="BANK"?"123456":null,kind=="BANK"?(10000000+Interlocked.Increment(ref serial)).ToString():null,kind=="BANK"?"HTT":null));
 private async Task<(Guid Bank,Guid Expense,Guid Revenue,Guid Gst,Guid Nt,Guid Fre)> Setup(HttpClient c,string basis="NON_CASH")
 {await CompanyTaxSettings.ConfigureAsync(db.Owner,db.Company,true,basis,DatabaseFixture.Issuer,db.Subject);var bank=await Bank(c);var exp=(Guid)(await S("INSERT INTO accounting.accounts(company_id,code,name,kind)VALUES(@company,@code,'C01 expense','EXPENSE')RETURNING id",("company",db.Company),("code",Code())))!;async Task<Guid> Tax(string code)=>(Guid)(await S("SELECT id FROM accounting.tax_codes WHERE company_id=@company AND code=@code",("company",db.Company),("code",code)))!;return(bank,exp,(Guid)(await S("SELECT id FROM accounting.accounts WHERE company_id=@company AND code='4000'",("company",db.Company)))!,await Tax("GST"),await Tax("N-T"),await Tax("FRE"));}
 private async Task<GeneralBankInput> Input(HttpClient c,string kind="PAY",string basis="NON_CASH")
 {var d=await Setup(c,basis);var date=await Today();return new(kind,d.Bank,date,Code(),"Settled non-trade source",true,[new(kind=="PAY"?d.Expense:d.Revenue,"C01 line",100,10,d.Gst,kind=="PAY"?"NON_CAPITAL":"TAXABLE")],kind=="PAY"?Code():null,kind=="PAY"?date:null);}
 private static Task<HttpResponseMessage> Post(HttpClient c,GeneralBankInput x,string? key=null)=>Send(c,HttpMethod.Post,"/bank-transactions",x,key:key);
 private static Task<HttpResponseMessage> Reverse(HttpClient c,Guid id,long? version=2,string? key=null)=>Send(c,HttpMethod.Post,$"/bank-transactions/{id}/reverse",new BankTransactionReversalInput("rev-"+(key??Code()),"Wrong coding; source correction"),version,key);
 private async Task<JsonElement> Bas(HttpClient c,bool full=false,string method="ACCOUNTS",DateOnly? date=null){var day=date??await Today();return await Get(c,$"/accounting/reports/gst-bas?from={day:yyyy-MM-dd}&to={day.AddDays(1):yyyy-MM-dd}&reportingMethod={(full?"FULL":"SIMPLER")}&calculationMethod={method}");}
 private static decimal F(JsonElement r,string key,bool full=false)=>D(full?r.GetProperty("financial").GetProperty("full").GetProperty(key):r.GetProperty("financial").GetProperty(key));
 [Theory][InlineData("PAY","CASH")][InlineData("PAY","NON_CASH")][InlineData("RECEIVE","CASH")][InlineData("RECEIVE","NON_CASH")]
 public async Task Settled_cash_posts_once_and_reconciles_GST_full_BAS_cash_flow_and_ledgers(string kind,string basis)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await Input(c,kind,basis);var a=await Expect(await Post(c,x),HttpStatusCode.Created);Assert.Equal("POSTED",a.GetProperty("transaction").GetProperty("state").GetString());Assert.Equal(110,D(a.GetProperty("transaction").GetProperty("gross")));foreach(var field in new[]{"net","tax","recoverableTax"})Assert.Equal(JsonValueKind.String,a.GetProperty("lines")[0].GetProperty(field).ValueKind);var r=await Bas(c);Assert.Equal("RECONCILED",r.GetProperty("ledgerStatus").GetString());Assert.Equal(kind=="RECEIVE"?110:0,F(r,"G1"));Assert.Equal(kind=="RECEIVE"?10:0,F(r,"1A"));Assert.Equal(kind=="PAY"?10:0,F(r,"1B"));foreach(var method in new[]{"ACCOUNTS","WORKSHEET"}){var full=await Bas(c,true,method);Assert.True(full.GetProperty("status").GetString()=="READY",full.GetRawText());Assert.Equal(kind=="PAY"?110:0,F(full,"G11",true));Assert.Equal(0,F(full,"purchaseGrossDifference",true));}await FinancialReportAssertions.Check(c);await Expect(await Reverse(c,Tid(a)),HttpStatusCode.OK);Assert.Equal(0,F(await Bas(c),"netGst"));await FinancialReportAssertions.Check(c);}
 [Fact] public async Task Transfer_has_two_legs_and_never_generates_income_or_GST()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Setup(c);var to=await Bank(c);var x=new BankTransferInput(d.Bank,to,await Today(),80,Code(),"Own funds");var a=await Expect(await Send(c,HttpMethod.Post,"/bank-transfers",x),HttpStatusCode.Created);Assert.Empty(a.GetProperty("lines").EnumerateArray());var id=Tid(a);Assert.Equal(2L,await S("SELECT count(*)FROM accounting.journal_lines WHERE company_id=@company AND journal_entry_id=@j",("company",db.Company),("j",a.GetProperty("transaction").GetProperty("journalEntryId").GetGuid())));Assert.Equal(0,F(await Bas(c),"G1"));await FinancialReportAssertions.Check(c);await Expect(await Reverse(c,id),HttpStatusCode.OK);await FinancialReportAssertions.Check(c);}

 private async Task<(Guid Statement,Guid Line)> Statement(HttpClient c,Guid bank,decimal amount,DateOnly? on=null)
 {var date=on??await Today();var a=await Expect(await Send(c,HttpMethod.Post,$"/bank-accounts/{bank}/statements/import",new BankStatementImportInput(Code(),date,date,0,amount,amount==0?[]:[new(date,amount,"C01 bank line")])),HttpStatusCode.Created);return(Id(a.GetProperty("statement")),a.GetProperty("lines").GetArrayLength()==0?Guid.Empty:Id(a.GetProperty("lines")[0]));}
 private static Task<HttpResponseMessage> Classify(HttpClient c,Guid line,GeneralBankInput x,long? version=1,string? key=null)=>Send(c,HttpMethod.Post,$"/bank-statement-lines/{line}/classify",new BankClassificationInput(x.Reference,x.Reason,x.NoPriorPostingConfirmed,x.Lines,x.TaxInvoiceReference,x.TaxInvoiceHeldOn),version,key);
 [Theory][InlineData("PAY")][InlineData("RECEIVE")]public async Task Classification_posts_and_matches_atomically_and_can_be_reconciled(string kind)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await Input(c,kind);var st=await Statement(c,x.BankAccountId,kind=="PAY"?-110:110);var a=await Expect(await Classify(c,st.Line,x),HttpStatusCode.Created);Assert.Single(a.GetProperty("activeMatches").EnumerateArray());var current=await Get(c,$"/bank-statements/{st.Statement}");Assert.Equal(2,current.GetProperty("statement").GetProperty("version").GetInt64());await Expect(await Send(c,HttpMethod.Post,$"/bank-statements/{st.Statement}/reconcile",new BankReconcileInput(Code(),"Balanced source"),2),HttpStatusCode.Created);await Expect(await Reverse(c,Tid(a)),HttpStatusCode.Conflict);await FinancialReportAssertions.Check(c);}
 [Fact]public async Task Partial_classification_consumes_only_remaining_statement_amount()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await Input(c);var st=await Statement(c,x.BankAccountId,-110);var half=x with{Lines=[x.Lines![0]with{Net=50,Tax=5}]};await Expect(await Classify(c,st.Line,half),HttpStatusCode.Created);await Expect(await Classify(c,st.Line,x with{Reference=Code()},2),HttpStatusCode.Conflict);await Expect(await Classify(c,st.Line,half with{Reference=Code()},2),HttpStatusCode.Created);Assert.Equal(10,F(await Bas(c),"1B"));Assert.Equal(2L,await S("SELECT count(*)FROM accounting.bank_transactions WHERE company_id=@company",("company",db.Company)));}
 [Theory][InlineData("post")][InlineData("classify")][InlineData("transfer")]
 public async Task Same_key_replays_and_changed_content_is_rejected(string operation)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await Input(c);var key=Code();Guid line=Guid.Empty;Guid other=Guid.Empty;if(operation=="classify")line=(await Statement(c,x.BankAccountId,-110)).Line;if(operation=="transfer")other=await Bank(c);Task<HttpResponseMessage> Run(bool changed=false)=>operation switch{"classify"=>Classify(c,line,x with{Reason=changed?"Changed":x.Reason},key:key),"transfer"=>Send(c,HttpMethod.Post,"/bank-transfers",new BankTransferInput(x.BankAccountId,other,x.OccurredOn,changed?120:110,x.Reference,x.Reason),key:key),_=>Post(c,x with{Reason=changed?"Changed":x.Reason},key)};var a=await Expect(await Run(),HttpStatusCode.Created);var b=await Expect(await Run(),HttpStatusCode.Created);Assert.True(JsonElement.DeepEquals(a,b));await Expect(await Run(true),HttpStatusCode.Conflict);Assert.Equal(1L,await S("SELECT count(*)FROM accounting.bank_transactions WHERE company_id=@company",("company",db.Company)));}
 [Theory][InlineData("post",true)][InlineData("post",false)][InlineData("classify",true)][InlineData("classify",false)][InlineData("transfer",true)][InlineData("transfer",false)]
 public async Task Concurrent_requests_create_one_source_per_business_fact(string operation,bool sameKey)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await Input(c);var key=Code();var line=operation=="classify"?(await Statement(c,x.BankAccountId,-110)).Line:Guid.Empty;var other=operation=="transfer"?await Bank(c):Guid.Empty;Task<HttpResponseMessage> Run(string k)=>operation switch{"classify"=>Classify(c,line,x,key:k),"transfer"=>Send(c,HttpMethod.Post,"/bank-transfers",new BankTransferInput(x.BankAccountId,other,x.OccurredOn,110,x.Reference,x.Reason),key:k),_=>Post(c,x,k)};var all=await Task.WhenAll(Run(key),Run(sameKey?key:Code()));if(sameKey){var a=await Expect(all[0],HttpStatusCode.Created);var b=await Expect(all[1],HttpStatusCode.Created);Assert.True(JsonElement.DeepEquals(a,b));}else{Assert.Single(all,r=>r.StatusCode==HttpStatusCode.Created);Assert.Single(all,r=>r.StatusCode==HttpStatusCode.Conflict);}Assert.Equal(1L,await S("SELECT count(*)FROM accounting.bank_transactions WHERE company_id=@company",("company",db.Company)));}
