 [Fact]public async Task Account_transfer_can_be_matched_on_each_bank_and_each_bank_reconciles()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Setup(c);var to=await Bank(c);var day=await Today();var a=await Expect(await Send(c,HttpMethod.Post,"/bank-transfers",new BankTransferInput(d.Bank,to,day,70,Code(),"Own funds")),HttpStatusCode.Created);foreach(var(bank,amt)in new[]{(d.Bank,-70m),(to,70m)}){var st=await Statement(c,bank,amt);var line=(Guid)(await S("SELECT id FROM accounting.journal_lines WHERE company_id=@company AND journal_entry_id=@j AND account_id=@bank",("company",db.Company),("j",a.GetProperty("transaction").GetProperty("journalEntryId").GetGuid()),("bank",bank)))!;await Expect(await Send(c,HttpMethod.Post,$"/bank-statement-lines/{st.Line}/matches",new BankMatchInput(Code(),"Own account movement",[new(line,70)]),1),HttpStatusCode.Created);await Expect(await Send(c,HttpMethod.Post,$"/bank-statements/{st.Statement}/reconcile",new BankReconcileInput(Code(),"Difference zero"),2),HttpStatusCode.Created);}await Expect(await Reverse(c,Tid(a)),HttpStatusCode.Conflict);await FinancialReportAssertions.Check(c);}
 [Theory][InlineData("post")][InlineData("classify")][InlineData("transfer")][InlineData("reverse")]
 public async Task Late_audit_failure_rolls_back_every_effect_then_same_key_retries(string operation)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await Input(c);var key=Code();Guid source=Guid.Empty;Guid line=Guid.Empty;Guid other=Guid.Empty;if(operation=="reverse")source=Tid(await Expect(await Post(c,x),HttpStatusCode.Created));if(operation=="classify")line=(await Statement(c,x.BankAccountId,-110)).Line;if(operation=="transfer")other=await Bank(c);var action=operation switch{"post"=>"accounting.general_bank_posted","classify"=>"accounting.bank_line_classified","transfer"=>"accounting.bank_transferred",_=>"accounting.general_bank_reversed"};Task<HttpResponseMessage> Run()=>operation switch{"classify"=>Classify(c,line,x,key:key),"reverse"=>Reverse(c,source,key:key),"transfer"=>Send(c,HttpMethod.Post,"/bank-transfers",new BankTransferInput(x.BankAccountId,other,x.OccurredOn,110,x.Reference,x.Reason),key:key),_=>Post(c,x,key)};await S($"CREATE FUNCTION accounting.test_c01_failure()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NEW.company_id='{db.Company}'::uuid AND NEW.action='{action}'THEN RAISE EXCEPTION 'Injected audit failure' USING ERRCODE='HR422';END IF;RETURN NEW;END$$;CREATE TRIGGER test_c01_failure BEFORE INSERT ON platform.audit_events FOR EACH ROW EXECUTE FUNCTION accounting.test_c01_failure()");try{await Expect(await Run(),HttpStatusCode.UnprocessableEntity);Assert.Equal(operation=="reverse"?1L:0L,await S("SELECT count(*)FROM accounting.journal_entries WHERE company_id=@company",("company",db.Company)));Assert.Equal(0L,await S("SELECT count(*)FROM accounting.bank_matches WHERE company_id=@company",("company",db.Company)));}finally{await S("DROP TRIGGER test_c01_failure ON platform.audit_events;DROP FUNCTION accounting.test_c01_failure()");}await Expect(await Run(),operation=="reverse"?HttpStatusCode.OK:HttpStatusCode.Created);}
 [Theory][InlineData(true)][InlineData(false)]public async Task Bank_reconciliation_and_posting_serialize_in_both_orders(bool reconcileFirst)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await Input(c);var st=await Statement(c,x.BankAccountId,0);await using var held=await db.SessionAsync();if(reconcileFirst){await Sql.RowsAsync(held,"SELECT accounting.finalize_bank_reconciliation(@id,1,'first','Verified','[]')",default,("id",st.Statement));var posting=Post(c,x);await Task.Delay(150);Assert.False(posting.IsCompleted);await held.Transaction.CommitAsync();await Expect(await posting,HttpStatusCode.Conflict);}else{await DirectPost(held,x);var reconciliation=Send(c,HttpMethod.Post,$"/bank-statements/{st.Statement}/reconcile",new BankReconcileInput(Code(),"Verified"),1);await Task.Delay(150);Assert.False(reconciliation.IsCompleted);await held.Transaction.CommitAsync();await Expect(await reconciliation,HttpStatusCode.Created);}await FinancialReportAssertions.Check(c);}
 private static async Task<Guid> DirectPost(CompanySession session,GeneralBankInput x)
 {var rows=await Sql.RowsAsync(session,"SELECT accounting.post_general_banking(@kind,@bank,NULL,@date,@reference,@reason,@lines::jsonb,NULL,NULL,true,@evidence,@held)AS id",default,("kind",x.Kind),("bank",x.BankAccountId),("date",x.OccurredOn),("reference",x.Reference),("reason",x.Reason),("lines",JsonSerializer.Serialize(x.Lines,new JsonSerializerOptions(JsonSerializerDefaults.Web))),("evidence",x.TaxInvoiceReference!),("held",x.TaxInvoiceHeldOn!.Value));return(Guid)rows.Single()["id"]!;}
 [Theory][InlineData(true)][InlineData(false)]public async Task BAS_finalization_and_new_source_serialize_without_lost_tax(bool finalizedFirst)
