 private async Task<(Guid Year,Guid Period,DateOnly From,DateOnly To)> HistoricalCalendar(bool monthly=false)
 {var start=new DateOnly(2024,7,1);var end=new DateOnly(2025,7,1);var year=(Guid)(await S("INSERT INTO accounting.fiscal_years(company_id,label,starts_on,ends_on,created_by)VALUES(@company,@label,@from,@to,@actor)RETURNING id",("company",db.Company),("label",Code()),("from",start),("to",end),("actor",db.Actor)))!;var to=monthly?start.AddMonths(1):end;var period=(Guid)(await S("INSERT INTO accounting.periods(company_id,fiscal_year_id,starts_on,ends_on,created_by)VALUES(@company,@year,@from,@to,@actor)RETURNING id",("company",db.Company),("year",year),("from",start),("to",to),("actor",db.Actor)))!;return(year,period,start,to);}
